<section class="panel"><form class="filters" method="get"><label class="search"><span>⌕</span><input name="q" value="<?=e($q)?>" placeholder="جست‌وجوی نام یا محتوا…"></label><select name="type"><option value="">همه نوع‌ها</option><option value="static" <?=$type==='static'?'selected':''?>>ثابت</option><option value="dynamic" <?=$type==='dynamic'?'selected':''?>>پویا</option></select><select name="status"><option value="">همه وضعیت‌ها</option><option value="active" <?=$status==='active'?'selected':''?>>فعال</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>غیرفعال</option></select><button class="secondary">اعمال فیلتر</button></form><?php if(!$items):?><div class="empty"><span>⌁</span><h3>کدی پیدا نشد</h3><p>فیلترها را تغییر دهید یا نخستین کد را بسازید.</p><a class="primary" href="<?=e(url('/qr-codes/create'))?>">ساخت کد QR</a></div><?php else:?><?=renderQrTable($items)?><?php if($pages>1):?><nav class="pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'current':''?>" href="?<?=http_build_query(['q'=>$q,'type'=>$type,'status'=>$status,'page'=>$i])?>"><?=fa_number($i)?></a><?php endfor?></nav><?php endif?><?php endif?></section>

